// Récupère l'id d'un candidat de ton périmètre pour tester l'historique d'actions.
const probes = $('Liste des tests').all().map(i => i.json.probe);
const res = $('Appels Boond').all();
const idx = probes.indexOf('cand_manager');
const body = res[idx] && res[idx].json.body;
const id = body && Array.isArray(body.data) && body.data[0] ? body.data[0].id : null;
if (!id) return [{ json: { probe: 'cand_actions_skipped', url: null } }];
const B = 'https://ui.boondmanager.com/api';
return [
  { json: { probe: 'cand_actions_default', url: `${B}/candidates/${id}/actions` } },
  { json: { probe: 'cand_actions_500', url: `${B}/candidates/${id}/actions?maxResults=500` } }
];

// Résumé SANS données personnelles : compteurs, noms de champs, codes. Aucune valeur de fiche.
const ACTION_CODES = [131, 15, 16, 18, 1, 19, 40, 130, 45, 134, 43];

function summarize(probe, url, r) {
  if (!url) return { probe, note: 'non exécuté' };
  const body = typeof r.body === 'string' ? (() => { try { return JSON.parse(r.body); } catch { return r.body; } })() : r.body;
  const out = { probe, url: url.replace('https://ui.boondmanager.com/api', ''), status: r.statusCode };
  if (!body || typeof body !== 'object') { out.raw = String(body).slice(0, 200); return out; }
  if (body.errors) out.errors = body.errors.map(e => e.detail || e.title || e.code);
  out.totalsRows = body.meta?.totals?.rows ?? null;
  const data = body.data;
  out.returned = Array.isArray(data) ? data.length : (data ? 1 : 0);
  const first = Array.isArray(data) ? data[0] : null;
  if (first) {
    out.type = first.type;
    out.attributeKeys = Object.keys(first.attributes || {});
    out.relationshipKeys = Object.keys(first.relationships || {});
    if (probe.startsWith('actions') || probe.startsWith('cand_actions')) {
      out.typeOfSample = [...new Set(data.map(a => a.attributes?.typeOf))].slice(0, 30);
      out.dependsOnType = first.relationships?.dependsOn?.data?.type ?? null;
      out.dates = data.slice(0, 3).map(a => a.attributes?.startDate);
    }
  }
  if (probe === 'dictionary') {
    const lists = [];
    (function walk(node, path) {
      if (lists.length > 80 || !node || typeof node !== 'object') return;
      if (Array.isArray(node)) {
        if (node.length && node.every(x => x && typeof x === 'object' && 'id' in x && ('value' in x || 'label' in x))) {
          const ids = node.map(x => Number(x.id));
          const relevant = /state|action/i.test(path) || ACTION_CODES.filter(c => ids.includes(c)).length >= 5;
          lists.push({ path, length: node.length, values: relevant ? node.slice(0, 80).map(x => `${x.id}=${x.value ?? x.label}`) : undefined });
        } else node.slice(0, 50).forEach((x, i) => walk(x, `${path}[${i}]`));
        return;
      }
      for (const k of Object.keys(node)) walk(node[k], path ? `${path}.${k}` : k);
    })(body, '');
    out.lists = lists.filter(l => l.values);
    out.otherListPaths = lists.filter(l => !l.values).map(l => l.path).slice(0, 40);
  }
  return out;
}

const rows = [];
const p1 = $('Liste des tests').all(), r1 = $('Appels Boond').all();
p1.forEach((p, i) => rows.push(summarize(p.json.probe, p.json.url, r1[i]?.json || {})));
const p2 = $('Tests historique candidat').all(), r2 = $('Appels historique').all();
p2.forEach((p, i) => rows.push(summarize(p.json.probe, p.json.url, r2[i]?.json || {})));

const base = rows.find(r => r.probe === 'cand_base')?.totalsRows;
const actBase = rows.find(r => r.probe === 'actions_base')?.totalsRows;
for (const r of rows) {
  if (r.probe.startsWith('cand_') && r.probe !== 'cand_base' && !r.probe.startsWith('cand_actions')) r.filtreActif = r.totalsRows !== base;
  if (r.probe.startsWith('actions_') && r.probe !== 'actions_base') r.filtreActif = r.totalsRows !== actBase;
}
return [{ json: { aCopierPourClaude: JSON.stringify(rows, null, 1) } }];
